new='''_ZERO = {"CLP", "ISK", "JPY", "KRW", "UGX", "VND"}
_THREE = {"BHD", "JOD", "KWD", "OMR", "TND"}
_LOCALES = {"en-US", "en-GB", "en-IN", "de-DE", "de-CH", "fr-FR", "pt-BR", "es", "ja-JP"}
_LINKS = {
    "US/Pacific": "America/Los_Angeles", "US/Eastern": "America/New_York", "US/Central": "America/Chicago",
    "Asia/Calcutta": "Asia/Kolkata", "Asia/Saigon": "Asia/Ho_Chi_Minh", "Europe/Kiev": "Europe/Kyiv",
    "America/Buenos_Aires": "America/Argentina/Buenos_Aires", "Brazil/East": "America/Sao_Paulo",
    "UTC": "Etc/UTC", "GMT": "Etc/UTC",
}
# locale -> (decimal, group, code before?)
_STYLE = {
    "en-US": (".", ",", True), "en-GB": (".", ",", True), "ja-JP": (".", ",", True), "en-IN": (".", ",", True),
    "pt-BR": (",", ".", True), "de-DE": (",", ".", False), "es": (",", ".", False),
    "de-CH": (".", "\\u2019", False), "fr-FR": (",", "\\u202f", False),
}


def _digits(currency: str) -> int:
    return 0 if currency in _ZERO else 3 if currency in _THREE else 2


def _zone(tz: str) -> str:
    tz = tz.strip()
    m = re.fullmatch(r"(?:UTC|GMT)?\\s*([+-\\u2212])\\s*(\\d{1,2})(?::?(\\d{2}))?", tz)
    if m:
        hours = int(m.group(2))
        sign = -1 if m.group(1) == "-" else 1
        if hours == 0:
            return "Etc/UTC"
        return f"Etc/GMT{'-' if sign > 0 else '+'}{hours}"
    return _LINKS.get(tz, tz)


def _locale(loc: str) -> str:
    base = re.split(r"[.@]", loc.strip())[0].replace("_", "-")
    parts = base.split("-")
    lang = parts[0].lower()
    tag = lang + ("-" + parts[1].upper() if len(parts) > 1 and parts[1] else "")
    if tag in _LOCALES:
        return tag
    if lang in _LOCALES:
        return lang
    return "en-US"


def _group(intpart: str, loc: str) -> str:
    if loc == "es" and len(intpart) <= 4:
        return intpart
    sep = _STYLE[loc][1]
    if loc == "en-IN" and len(intpart) > 3:
        head, tail = intpart[:-3], intpart[-3:]
        pieces = []
        while len(head) > 2:
            pieces.insert(0, head[-2:])
            head = head[:-2]
        if head:
            pieces.insert(0, head)
        return sep.join(pieces + [tail])
    pieces = []
    while len(intpart) > 3:
        pieces.insert(0, intpart[-3:])
        intpart = intpart[:-3]
    pieces.insert(0, intpart)
    return sep.join(pieces)


def _format(value: Decimal, currency: str, loc: str) -> str:
    dec, _, before = _STYLE[loc]
    n = _digits(currency)
    text = f"{abs(value):.{n}f}"
    intpart, _, frac = text.partition(".")
    num = _group(intpart, loc) + (dec + frac if n else "")
    if value < 0:
        num = "-" + num
    nb = "\\u00a0"
    return f"{currency}{nb}{num}" if before else f"{num}{nb}{currency}"


def _amount(value: str, n: int) -> Decimal:
    return Decimal(value).quantize(Decimal(1).scaleb(-n), rounding=ROUND_HALF_EVEN)


def monthly_statement(transport: Transport, merchant: Merchant, year: int, month: int) -> Statement:
    """The statement of `merchant` for one calendar month, with its days in the merchant's time zone.

    One line per day that has settlements, in day order, with the figures and the text the
    Meridale dashboard shows. Raises ApiError when the API answers with an error.
    """
    first = date(year, month, 1)
    end = date(year + month // 12, month % 12 + 1, 1)
    loc = _locale(merchant.locale)
    params = {
        "merchant_id": merchant.id,
        "tz": _zone(merchant.tz),
        "from": first.isoformat(),
        "to": end.isoformat(),
        "locale": loc,
    }
    report = _call(transport, "GET", f"{BASE}/settlements", params)
    cur = report["currency"]
    n = _digits(cur)
    lines = []
    for d in report["days"]:
        gross, fees, refunds = _amount(d["gross"], n), _amount(d["fees"], n), _amount(d["refunds"], n)
        net = gross - fees - refunds
        lines.append(Line(date.fromisoformat(d["day"]), gross, fees, refunds, net, _format(net, cur, loc)))
    total = sum((line.net for line in lines), Decimal(0)).quantize(Decimal(1).scaleb(-n))
    return Statement(merchant.id, cur, tuple(lines), total, _format(total, cur, loc))
'''
s=s[:a]+new
s=s.replace("import json\n","import json\nimport re\n").replace("from decimal import Decimal","from decimal import ROUND_HALF_EVEN, Decimal")
